effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float px = 1.0 / max(acScreenSize.y, 1.0);
  float l = gmLum(c);
  float lx = gmLum(texture2DCv(inputImg.texture, uv + vec2(px, 0.0)).rgb) - l;
  float ly = gmLum(texture2DCv(inputImg.texture, uv + vec2(0.0, px)).rgb) - l;
  float rad = radians(angle);
  float d = (lx * cos(rad) + ly * sin(rad)) * depth * 20.0;
  vec3 col = vec3(clamp(grey + d, 0.0, 1.0));
  col = mix(c, col, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
